def permutationsDivByK(digits: list[int], k: int) -> int:
    used = [False] * len(digits)
    count = 0
    def backtrack(curr_val, length):
        nonlocal count
        if length == len(digits):
            if curr_val % k == 0: count += 1
            return
        for i in range(len(digits)):
            if not used[i]:
                used[i] = True
                backtrack(curr_val * 10 + digits[i], length + 1)
                used[i] = False
    backtrack(0, 0)
    return count

